# Get actual bottle file sizes from brew API / github
python3 - <<'PY'
import json, urllib.request, ssl
ssl._create_default_https_context = ssl._create_unverified_context
# use formulae.brew.sh API
formulas = ['jadx','apktool','radare2','openjdk','ghidra','binwalk','nuclei','android-platform-tools','graphviz','plantuml','nmap','hashcat','sqlmap','ffuf']
for name in formulas:
    url=f'https://formulae.brew.sh/api/formula/{name}.json'
    try:
        with urllib.request.urlopen(url, timeout=15) as r:
            d=json.load(r)
        files=((d.get('bottle') or {}).get('stable') or {}).get('files') or {}
        # prefer arm64 mac
        pick=None
        for k in files:
            if 'arm64' in k:
                pick=(k, files[k]); break
        if not pick and files:
            k=next(iter(files)); pick=(k, files[k])
        size = pick[1].get('size') if pick else None
        ver=d.get('versions',{}).get('stable')
        mb = f"{size/1024/1024:.1f} MB" if size else 'n/a'
        print(f"{name:24s} v{ver:10s} bottle={mb:10s} key={pick[0] if pick else '-'}")
    except Exception as e:
        print(f"{name:24s} ERR {e}")

# casks approximate via API
for name in ['ghidra','burp-suite','temurin','android-platform-tools']:
    url=f'https://formulae.brew.sh/api/cask/{name}.json'
    try:
        with urllib.request.urlopen(url, timeout=15) as r:
            d=json.load(r)
        # no reliable size; print url
        print(f"cask:{name:20s} ver={d.get('version')} url={(d.get('url') or '')[:70]}")
    except Exception as e:
        print(f"cask:{name} ERR {e}")
