            cand=f; break
    if not cand:
        for f in files:
            if f['filename'].endswith('.whl'):
                cand=f; break
    if cand:
        print(f"pypi:{pkg:12s} v{ver} file={cand['filename']} size={cand['size']/1024/1024:.1f} MB")
    else:
        print(f"pypi:{pkg} no file")
