python3 - <<'PY'
from pathlib import Path
import os, json, collections, itertools
base = Path.home()/'Library'/'Application Support'
cands=[]
for app in ['Code','Code - Insiders']:
    ws = base/app/'User'/'workspaceStorage'
    if not ws.exists():
        continue
    for d in ws.iterdir():
        c=d/'chatSessions'
        if not c.exists():
            continue
        for f in c.glob('*.jsonl'):
            try:
                st=f.stat()
                cands.append((st.st_mtime, st.st_size, f, app))
            except Exception:
                pass
cands.sort(reverse=True)
print('total jsonl', len(cands))
for m,s,f,app in cands[:15]:
    print(f'{s/1024/1024:8.2f}MB  {app:16s}  {f}')

# pick best: newest under 3MB, else newest under 10MB, else head of newest large
pick=None
for m,s,f,app in cands:
    if s <= 3*1024*1024:
        pick=(f,s,app); break
if not pick:
    for m,s,f,app in cands:
        if s <= 10*1024*1024:
            pick=(f,s,app); break
if not pick and cands:
    pick=(cands[0][2], cands[0][1], cands[0][3])
print('PICK', pick)
if pick:
    Path('/tmp/cr_jsonl_pick').write_text(str(pick[0]))
