from pathlib import Path
import json, collections, statistics, re, copy

work = Path('/Users/xin/Desktop/sidecar_remote/analysis/copilot-remote-0.4.1')
out = work/'jsonl'
out.mkdir(parents=True, exist_ok=True)

files = [
  Path('/Users/xin/Library/Application Support/Code/User/workspaceStorage/4cfb0b6fc59d641b94989f31b1b09c06/chatSessions/aaded402-24a6-44cc-9c95-f48ea6e7cc8c.jsonl'),
  Path('/Users/xin/Library/Application Support/Code/User/workspaceStorage/4cfb0b6fc59d641b94989f31b1b09c06/chatSessions/eab05fee-0bc4-450d-a5da-4ec5a62783dd.jsonl'),  # current ~7MB
  Path('/Users/xin/Library/Application Support/Code/User/workspaceStorage/31c13c0c390f5d1377fc9ce9b9c55cbd/chatSessions/9c9a327a-4c08-4379-aabf-e790942a895f.jsonl'),
]

# Reimplement Remote's processChatEntry semantics against real data

IGNORE_KINDS = {
  'progressMessage','mcpServersStarting','undoStop','prepareToolInvocation',
  # from earlier string set near prepareToolInvocation - expand from extension if needed
}

def path_key(k):
    if isinstance(k, list):
        return tuple(k)
    return (k,)

def analyze_file(path, max_lines=200000):
    kind_counter = collections.Counter()
    k0_counter = collections.Counter()
    k_full_counter = collections.Counter()
    response_part_kinds = collections.Counter()
    user_fields = collections.Counter()
    samples = { 'requests_replace': [], 'response_replace': [], 'response_splice': [], 'finalize': [], 'user': [], 'tool': [], 'confirm': [], 'other_top': [] }
    line_count=0
    parse_err=0
    # simulate remote state
    resp_parts = {}
    seen_req = set()
    events = []  # phone-bound events summary

    def handle_user_request(t):
        rid = (t or {}).get('requestId') or ''
        if not rid or rid in seen_req:
            return
        seen_req.add(rid)
        # field extraction like remote
        msg = t.get('message') if isinstance(t, dict) else None
        text = None
        if isinstance(msg, dict):
            text = msg.get('text') or msg.get('value')
            for fk in msg.keys():
                user_fields[f'message.{fk}'] += 1
        if not text and isinstance(t, dict):
            for fk in ['text','prompt','content','value']:
                if t.get(fk):
                    text = t.get(fk); user_fields[fk]+=1; break
        for fk in (t or {}).keys():
            user_fields[f'req.{fk}'] += 1
        if text:
            events.append(('USER_MESSAGE', str(text)[:120]))
            if len(samples['user'])<5:
                samples['user'].append({'requestId': rid, 'keys': list(t.keys()), 'message_keys': list(msg.keys()) if isinstance(msg,dict) else None, 'text': str(text)[:200]})

    def render_blocks(parts):
        blocks=[]
        for p in parts or []:
            if not isinstance(p, dict):
                continue
            kind = p.get('kind') or ''
            if kind in IGNORE_KINDS:
                continue
            if kind in ('toolInvocationSerialized','toolInvocation'):
                inv = p.get('invocationMessage') or p.get('pastTenseMessage') or {}
                if isinstance(inv, str):
                    n=inv
                elif isinstance(inv, dict):
                    n=inv.get('value') or inv.get('content') or ''
                else:
                    n=''
                blocks.append({'type':'tool','toolId': p.get('toolCallId') or p.get('toolId'), 'text': n or p.get('toolId') or 'tool', 'isComplete': p.get('isComplete', True), 'kind': kind})
                response_part_kinds[kind]+=1
                if len(samples['tool'])<8:
                    samples['tool'].append({kk:p.get(kk) for kk in list(p.keys())[:20]})
            elif kind=='confirmation' or (not kind and p.get('buttons')):
                blocks.append({'type':'confirm','title':p.get('title'),'message':str(p.get('message') or '')[:100],'buttons':p.get('buttons')})
                response_part_kinds['confirmation']+=1
                if len(samples['confirm'])<5:
                    samples['confirm'].append({kk:p.get(kk) for kk in list(p.keys())[:20]})
            elif not kind and isinstance(p.get('value'), str):
                blocks.append({'type':'text','text':p.get('value')})
                response_part_kinds['text_value']+=1
            else:
                response_part_kinds[kind or f'other:{list(p.keys())[:4]}'] += 1
        return blocks

    def apply_response_mutation(path, idx, v, i):
        key=path
        cur = resp_parts.get(key, [])
        if not isinstance(i, int):
            resp_parts[key] = list(v) if isinstance(v, list) else v
        else:
            # splice semantics from remote: i.splice(n,0,...r)
            if not isinstance(cur, list):
                cur=[]
            cur[i:i] = list(v) if isinstance(v, list) else [v]
            resp_parts[key]=cur
        blocks = render_blocks(resp_parts.get(key) or [])
        # summarize
        for b in blocks:
            if b['type']=='text':
                events.append(('STREAM_SET', b['text'][:80]))
            elif b['type']=='tool':
                events.append(('TOOL_CALL', b.get('text','')[:80]))
            elif b['type']=='confirm':
                events.append(('AGENT_CONFIRM', b.get('title')))

    with path.open('r', errors='ignore') as f:
        for line in f:
            if line_count >= max_lines:
                break
            line=line.strip()
            if not line:
                continue
            line_count += 1
            try:
                o=json.loads(line)
            except Exception:
                parse_err += 1
                continue
            kind = o.get('kind')
            kind_counter[kind] += 1
            k = o.get('k')
            if isinstance(k, list) and k:
                k0_counter[str(k[0])] += 1
                # compact path pattern
                pat=[]
                for x in k:
                    if isinstance(x, int):
                        pat.append('#')
                    else:
                        pat.append(str(x))
                k_full_counter['/'.join(pat)] += 1
            # Remote processChatEntry
            if isinstance(k, list) and k and k[0]=='requests':
                # finalize?
                if len(k)==3 and isinstance(k[1], int) and k[2] in ('elapsedMs','result','isCanceled'):
                    events.append(('FINALIZE', k[1], k[2]))
                    if len(samples['finalize'])<8:
                        samples['finalize'].append({'k':k, 'kind':kind, 'v_type': type(o.get('v')).__name__, 'v': o.get('v') if not isinstance(o.get('v'), (dict,list)) else str(o.get('v'))[:120]})
                    continue
                if kind == 2:
                    if len(k)==1:
                        v=o.get('v')
                        if isinstance(v, list):
                            if len(samples['requests_replace'])<3:
                                samples['requests_replace'].append({'n': len(v), 'first_keys': list(v[0].keys()) if v and isinstance(v[0], dict) else None})
                            for req in v:
                                handle_user_request(req)
                        continue
                    if len(k)==3 and isinstance(k[1], int) and k[2]=='response':
                        v=o.get('v'); i=o.get('i')
                        bucket = 'response_splice' if isinstance(i,int) else 'response_replace'
                        if len(samples[bucket])<6:
                            # summarize v parts
                            summary=None
                            if isinstance(v, list):
                                summary=[{'keys': list(p.keys()) if isinstance(p,dict) else type(p).__name__, 'kind': (p.get('kind') if isinstance(p,dict) else None), 'value_prefix': (str(p.get('value'))[:60] if isinstance(p,dict) and 'value' in p else None)} for p in v[:5]]
                            samples[bucket].append({'k':k, 'i':i, 'v_len': len(v) if isinstance(v,list) else None, 'parts': summary})
                        apply_response_mutation(f'requests/{k[1]}/response', k[1], v, i)
                        continue
            else:
                if len(samples['other_top'])<15 and isinstance(k, list):
                    samples['other_top'].append({'kind':kind, 'k':k[:6], 'has_v': 'v' in o, 'has_i': 'i' in o})

    return {
        'file': str(path),
        'size': path.stat().st_size,
        'lines': line_count,
        'parse_err': parse_err,
        'kind_counter': kind_counter.most_common(),
        'k0_counter': k0_counter.most_common(30),
        'k_path_patterns': k_full_counter.most_common(40),
        'response_part_kinds': response_part_kinds.most_common(40),
        'user_fields': user_fields.most_common(40),
        'event_type_counts': collections.Counter(e[0] for e in events).most_common(),
        'events_sample': events[:40],
        'samples': samples,
        'seen_requests': len(seen_req),
        'resp_paths': list(resp_parts.keys())[:20],
    }

reports=[]
for f in files:
    if not f.exists():
        print('missing', f); continue
    # for large file limit lines
    max_lines = 50000 if f.stat().st_size > 5*1024*1024 else 200000
    print('analyzing', f.name, 'max_lines', max_lines)
    r=analyze_file(f, max_lines=max_lines)
    reports.append(r)
    (out/f'{f.stem}.summary.json').write_text(json.dumps(r, indent=2, ensure_ascii=False, default=str))
    print('  lines', r['lines'], 'kinds', r['kind_counter'][:5], 'events', r['event_type_counts'][:8])

# Cross-file synthesis
synth = {
  'files': [r['file'] for r in reports],
  'common_k0': None,
  'notes': []
}
# merge k0
c=collections.Counter()
for r in reports:
    c.update(dict(r['k0_counter']))
synth['common_k0']=c.most_common(20)
# merge response part kinds
c2=collections.Counter()
for r in reports:
    c2.update(dict(r['response_part_kinds']))
synth['response_part_kinds']=c2.most_common(30)
# kind values
c3=collections.Counter()
for r in reports:
    c3.update(dict(r['kind_counter']))
synth['kinds']=c3.most_common()

# Compare with extension expectations
ext = Path('/Users/xin/Desktop/sidecar_remote/atulhritik.copilot-remote-0.4.1/dist/extension.js').read_text(errors='ignore')
# extract ignore set near prepareToolInvocation
m=re.search(r'new Set\(\[([^\]]+)\]\)', ext)
ignore_sets=[]
for m in re.finditer(r'Set\(\[([^\]]{0,500})\]\)', ext):
    s=m.group(1)
    if 'prepareToolInvocation' in s or 'progressMessage' in s:
        ignore_sets.append(s)
synth['extension_ignore_set_raw']=ignore_sets[:2]

(out/'SYNTHESIS.json').write_text(json.dumps(synth, indent=2, ensure_ascii=False))
print('\nSYNTHESIS kinds', synth['kinds'])
print('k0', synth['common_k0'][:15])
print('resp kinds', synth['response_part_kinds'][:20])
print('ignore', ignore_sets[:1])
PY

